apiVersion: kafka.strimzi.io/v1beta2
kind: KafkaTopic
metadata:
  name: trades
spec:
  partitions: 10
  replicas: 3
  config:
    retention.ms: 604800000
    cleanup.policy: delete
    min.insync.replicas: 2
    segment.bytes: 10485760
    segment.ms: 60000
    compression.type: lzo

---
apiVersion: kafka.strimzi.io/v1beta2
kind: KafkaTopic
metadata:
  name: trades-enriched
spec:
  partitions: 10
  replicas: 3
  config:
    retention.ms: 604800000
    cleanup.policy: delete
    min.insync.replicas: 2
    segment.bytes: 10485760
    segment.ms: 60000
    compression.type: lzo

---
apiVersion: kafka.strimzi.io/v1beta2
